'use strict';
// C#'s file rules (src/languages/csharp/rules.js, C1): source, test and generated files,
// and the project a file belongs to. Paths are real ones from Jellyfin and eShop.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { csharpRules, csharpProjectOf, GENERATED_HEAD_CHARS } = require('../src/languages/csharp/rules');

test('a .cs file is C# source; build output is not', () => {
  for (const p of ['A.cs', 'Jellyfin.Server/Migrations/Routines/MigrateActivityLogDb.cs', 'a\\b\\C.cs', 'src/binary/X.cs', 'src/objects/X.cs', 'src/Debin/X.cs']) {
    assert.equal(csharpRules.handles(p), true, p);
  }
  for (const p of ['A.csx', 'A.cshtml', 'A.cs.orig', 'A.CS', 'A.csproj', 'src/X/bin/Debug/net8.0/X.cs', 'obj/Debug/X.AssemblyInfo.cs', 'src/X/obj/X.cs', 'bin\\X.cs']) {
    assert.equal(csharpRules.handles(p), false, p);
  }
});

test('a test is in a *.Tests-style project directory or named *Tests.cs', () => {
  for (const p of ['tests/Jellyfin.Api.Tests/Controllers/UserControllerTests.cs', 'src/Jellyfin.Naming.Tests/TV/X.cs', 'tests/ClientApp.UnitTests/ViewModels/CatalogViewModelTests.cs', 'tests/Ordering.UnitTests/Domain/BuyerAggregateTest.cs', 'x/Foo.IntegrationTests/A.cs', 'x/Foo.FunctionalTests/A.cs', 'src/Foo/BarTests.cs', 'tests\\Foo.Tests\\A.cs']) {
    assert.equal(csharpRules.isTest(p), true, p);
  }
  for (const p of ['src/Foo/SpeedTest.cs', 'src/Foo/Contests.cs', 'src/Foo/Tests/A.cs', 'src/Foo/Foo.Testing/A.cs', 'src/Foo.Tests.Utils/A.cs', 'src/Foo/Tests.cs.orig', 'src/Foo/BarTests.csx', 'Jellyfin.Server/Migrations/Routines/X.cs']) {
    // The shared `tests?/` directory rule is applied by the registry, not here.
    assert.equal(csharpRules.isTest(p), false, p);
  }
});

test('generated by file name: designers, source generators and EF migrations', () => {
  const body = 'namespace X { class A {} }\n';
  for (const p of [
    'Pages/Foo.g.cs', 'Pages/Foo.g.i.cs', 'Forms/Main.designer.cs', 'Forms/Main.Designer.cs', 'Api/Client.generated.cs',
    'src/Jellyfin.Database/Jellyfin.Database.Providers.Sqlite/Migrations/20200514181226_AddActivityLog.Designer.cs',
  ]) {
    assert.equal(csharpRules.isGenerated(p, body), true, p);
  }
  // EF's model snapshot: by name and EF's `ModelSnapshot` base class (as EF writes it).
  const snapshot = '// <auto-generated />\nusing System;\nusing Microsoft.EntityFrameworkCore;\nusing Microsoft.EntityFrameworkCore.Infrastructure;\n\n#nullable disable\n\nnamespace Ordering.Infrastructure.Migrations\n{\n    [DbContext(typeof(OrderingContext))]\n    partial class OrderingContextModelSnapshot : ModelSnapshot\n    {\n    }\n}\n';
  const snapshotNoMarker = 'namespace X\n{\n    [DbContext(typeof(JellyfinDbContext))]\n    partial class JellyfinDbModelSnapshot : ModelSnapshot\n    {\n    }\n}\n';
  assert.equal(csharpRules.isGenerated('src/Ordering.Infrastructure/Migrations/OrderingContextModelSnapshot.cs', snapshot), true, 'EF snapshot');
  assert.equal(csharpRules.isGenerated('src/Jellyfin.Database/Jellyfin.Database.Providers.Sqlite/Migrations/JellyfinDbModelSnapshot.cs', snapshotNoMarker), true, 'EF snapshot by base class');
  const viewModel = 'namespace App.ViewModels;\n\npublic sealed class ViewModelSnapshot : ObservableObject\n{\n}\n';
  assert.equal(csharpRules.isGenerated('src/ViewModelSnapshot.cs', viewModel), false, 'a view-model snapshot is hand-written');
  assert.equal(csharpRules.isGenerated('src/Migrations/OrderingContextModelSnapshot.cs', body), false, 'snapshot name without the base class');
  // A timestamped migration is generated when it derives from EF's `Migration`; Jellyfin's
  // hand-written startup routines have the same name shape and are not.
  const ef = 'namespace X { public partial class AddActivityLog : Migration { } }\n';
  for (const p of ['src/Jellyfin.Database/Jellyfin.Database.Providers.Sqlite/Migrations/20200514181226_AddActivityLog.cs', 'src\\Ordering.Infrastructure\\Migrations\\20231105123456_X.cs']) {
    assert.equal(csharpRules.isGenerated(p, ef), true, p);
  }
  const routine = 'namespace X { internal class DisableTranscodingThrottling : IAsyncMigrationRoutine { } }\n';
  assert.equal(csharpRules.isGenerated('Jellyfin.Server/Migrations/Routines/20250420050000_DisableTranscodingThrottling.cs', routine), false, 'startup routine');
  assert.equal(csharpRules.isGenerated('Jellyfin.Server/Migrations/Routines/20250420050000_DisableTranscodingThrottling.cs', ef.replace('Migration', 'IMigration')), false, 'IMigration is not EF');
  for (const p of ['Jellyfin.Server/Migrations/Routines/MigrateActivityLogDb.cs', 'Jellyfin.Server/Migrations/Routines/20200514_X.cs', 'src/Foo/Generated.cs', 'src/Foo/Designer.cs', 'src/Foo/Snapshot.cs', 'src/Foo/ModelSnapshotHelper.cs', 'src/Foo/Foo.generated.cs.orig']) {
    assert.equal(csharpRules.isGenerated(p, body), false, p);
  }
});

test('generated by an <auto-generated> comment in the head', () => {
  const yes = (/** @type {string} */ text, /** @type {string} */ why) => assert.equal(csharpRules.isGenerated('A.cs', text), true, why);
  const no = (/** @type {string} */ text, /** @type {string} */ why) => assert.equal(csharpRules.isGenerated('A.cs', text), false, why);
  yes('//------------------------------------------------------------------------------\n// <auto-generated>\n//     This code was generated by a tool.\n// </auto-generated>\n//------\nnamespace X {}\n', 'line comments');
  yes('/// <auto-generated/>\nnamespace X {}\n', 'doc comment, self-closed');
  yes('// <auto-generated />\r\n#nullable enable\r\nclass A {}\r\n', 'CRLF');
  yes('/*\n * <auto-generated>\n */\nclass A {}\n', 'block comment');
  yes('/* <auto-generated> */\nclass A {}\n', 'one-line block comment');
  no('namespace X { class A {} }\n', 'no marker');
  no('// This file is hand-written.\nclass A {}\n', 'plain comment');
  no('class A { string s = "<auto-generated"; }\n', 'in a string');
  no('', 'an empty file');
  // Only the file header counts: comments before the first code (usings and directives skipped).
  yes('using System;\n#nullable enable\n// <auto-generated/>\nclass A {}\n', 'after usings and a directive');
  yes('\uFEFF// <auto-generated>\nclass A {}\n', 'after a BOM');
  const generator = [
    'using System.Text;',
    'using Microsoft.CodeAnalysis;',
    '',
    'namespace Gen;',
    '',
    '[Generator]',
    'public sealed class EnumGenerator : IIncrementalGenerator',
    '{',
    '    // Emitted files start with an <auto-generated> header.',
    '    static string Emit(string name)',
    '    {',
    '        var sb = new StringBuilder();',
    '        sb.AppendLine("// <auto-generated/>");',
    '        sb.AppendLine("/* <auto-generated> */");',
    '        return sb.ToString();',
    '    }',
    '    const string Header = """',
    '        // <auto-generated/>',
    '        """;',
    '}',
  ].join('\n');
  no(generator, "a source generator's own code: the marker in strings and a later comment");
  no('namespace X;\n// <auto-generated>\nclass A {}\n', 'a comment after the first code');
  no('class A { string s = "// <auto-generated"; }\n', 'in a string with a comment marker');
  const late = `${'// filler\n'.repeat(Math.ceil(GENERATED_HEAD_CHARS / 10))}// <auto-generated>\nclass A {}\n`;
  no(late, 'past the head: analysed, as documented');
});

test('csharpProjectOf: the nearest directory with a .csproj', () => {
  const repo = fs.mkdtempSync(path.join(os.tmpdir(), 'it-cs-rules-'));
  try {
    fs.mkdirSync(path.join(repo, 'src', 'Api', 'Controllers'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'src', 'Core'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'loose'), { recursive: true });
    fs.writeFileSync(path.join(repo, 'src', 'Api', 'Api.csproj'), '');
    fs.writeFileSync(path.join(repo, 'src', 'Core', 'Core.csproj'), '');
    fs.writeFileSync(path.join(repo, 'src', 'Core', 'notes.txt'), '');
    assert.deepEqual(csharpProjectOf('src/Api/Controllers/X.cs', repo), { component: 'src/Api', projectRoot: 'src/Api' });
    assert.deepEqual(csharpProjectOf('src\\Api\\Controllers\\X.cs', repo), { component: 'src/Api', projectRoot: 'src/Api' }, 'Windows path');
    assert.deepEqual(csharpProjectOf('src/Core/Y.cs', repo), { component: 'src/Core', projectRoot: 'src/Core' });
    assert.deepEqual(csharpProjectOf('loose/Z.cs', repo), { component: '(no .csproj)', projectRoot: '' });
    assert.deepEqual(csharpProjectOf('Top.cs', repo), { component: '(no .csproj)', projectRoot: '' });
    fs.writeFileSync(path.join(repo, 'Root.csproj'), '');
    assert.deepEqual(csharpProjectOf('loose/Z.cs', repo), { component: '(root)', projectRoot: '' }, 'falls back to a root project');
    assert.deepEqual(csharpProjectOf('Top.cs', repo), { component: '(root)', projectRoot: '' });
  } finally {
    fs.rmSync(repo, { recursive: true, force: true });
  }
});
